72	export function generateNicheDescription(category) {
73	    return callTask('niche-description', { category });
74	}
75	
76	// "✨ Сгенерировать через ИИ" on a product's ROADMAP ПРОДВИЖЕНИЯ - suggests
77	// new milestones grounded in that product's own project-info fields
78	// (about/target audience/value proposition/differentiators), same
79	// preview-then-confirm shape as discoverRssSources/discoverKeywords.
80	// systemContext - общий срез системы (стратегия из контент-плана, выводы
81	// Insights, реальные метрики публикаций, состояние CRM), см.
82	// server/lib/systemContext.js. Собирается на стороне хаба и приходит сюда
83	// готовым текстом: агент по-прежнему получает узкие именованные параметры,
84	// а не произвольный промпт.
85	export function generateRoadmap({ productName, about, targetAudience, valueProposition, keyDifferentiators, existingTitles, systemContext }) {
86	    return callTask('roadmap', { productName, about, targetAudience, valueProposition, keyDifferentiators, existingTitles, systemContext }, { timeoutMs: 3 * 60 * 1000 });
87	}
88	
89	export function generateReelsScript(title, postText) {
90	    return callTask('reels-script', { title, postText });
91	}
92	
93	export function generateScriptSection({ heading, prompt, nicheName, nicheSubtitle, toneOfVoice }) {
94	    return callTask('script-section', { heading, prompt, nicheName, nicheSubtitle, toneOfVoice });
95	}
96	
97	// Runs on Sonnet server-side (see local-claude-agent/server.js), longer
98	// timeout than the other tasks - it can write up to 4 full pieces of copy in
99	// one call. `formats` (subset of tgPost/reelsScript/threads/pinterest)
100	// defaults to all 4 server-side when omitted/empty.
101	export function generateContentDraft({ topic, productContext, toneOfVoice, postFormula, formats, systemContext }) {
102	    return callTask('content-draft', { topic, productContext, toneOfVoice, postFormula, formats, systemContext }, { timeoutMs: 4 * 60 * 1000 });
103	}
104	
105	// Also Sonnet (see local-claude-agent/server.js) - a real topic pitch that
106	// gets typed straight into a publish-bound draft, using WebSearch to ground
107	// it in something actually current. `usedTopics` lets the caller keep
108	// re-rolling without getting the same suggestion twice.
109	export function suggestContentTopic({ productContext, usedTopics, strategyContext }) {
110	    return callTask('suggest-topic', { productContext, usedTopics, strategyContext }, { timeoutMs: 90 * 1000 });
111	}
112	
113	// Short timeout (vs the 3-minute default) - reviewing a handful of short
114	// legal findings is quick, and this is a nice-to-have enrichment on top of
115	// the url-checker's static scan, not something the caller should wait long
116	// for if the user's PC/tunnel happens to be slow to respond right now.
117	export function reviewLegalFindings(findings, snippets) {
118	    return callTask('legal-review', { findings, snippets }, { timeoutMs: 60 * 1000 });
119	}
120	
121	// Telegram-watch (see local-claude-agent/README.md "Telegram source
122	// watching") - a real user (MTProto) session on the same container/tunnel,
123	// not the publish bot, so it can read arbitrary public channels. Same
124	// graceful-no-op pattern (isLocalClaudeAgentConfigured() gates both) - the
125	// container itself further errors per-call if TELEGRAM_SESSION isn't set up
126	// yet, surfaced as a normal error by callTask above.
127	export function validateTelegramWatchChannel(username) {
128	    return callTask('telegram-add-channel', { username }, { timeoutMs: 30 * 1000 });
129	}
130	
131	export function scanTelegramWatchChannels(usernames, limit) {
132	    return callTask('telegram-scan-channels', { usernames, limit }, { timeoutMs: 2 * 60 * 1000 });
133	}

