letsencrypt_email: root@alba-creation.ru

# Shared secret between the hub backend and parser-worker (X-Worker-Token
# header). This placeholder is deliberately not a real secret - override it:
#   ansible-playbook site.yml -e parser_worker_token=$(openssl rand -hex 24) -e vnc_basic_auth_password=$(openssl rand -hex 12)
parser_worker_token: REDACTED
vnc_basic_auth_user: admin
vnc_basic_auth_password: REDACTED

sites:
  - name: alba-creation
    domain: alba-creation.ru
    www_alias: true
    proxy_port: 3002

  - name: coolify
    domain: coolify.alba-creation.ru
    www_alias: false
    proxy_port: 8000

  - name: hub
    domain: hub.alba-creation.ru
    www_alias: false
    proxy_port: 3001
    extra_locations:
      - |
        location /vnc/ {
            auth_basic "Parser worker VNC";
            auth_basic_user_file /etc/nginx/.vnc_htpasswd;
            proxy_pass http://127.0.0.1:6080/;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_set_header Host $host;
            proxy_read_timeout 3600s;
        }
